CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Warp-per-instance RMSNorm kernel specialized for C=64.
// blockDim.x = 128 (4 warps). Each warp handles one flattened instance.
// Lane i loads channels i and i+32, accumulates sum-of-squares,
// reduces within the warp via shuffle, then writes normalized output.
__global__ void rmsnorm_warp64_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t inner,   // product of trailing dims (H*W for NCHW)
    int64_t total_instances,
    float eps
) {
    // warp index within the grid
    int warp_id_in_block = threadIdx.x >> 5;  // threadIdx.x / 32
    int lane = threadIdx.x & 31;              // threadIdx.x % 32
    int64_t inst = (int64_t)blockIdx.x * 4 + warp_id_in_block;

    while (inst < total_instances) {
        // inst = n * inner + hw
        int64_t n  = inst / inner;
        int64_t hw = inst % inner;

        // In NCHW layout: element [n, c, hw] = n*(64*inner) + c*inner + hw
        int64_t base = n * 64 * inner + hw;

        float v0 = x[base + (int64_t)lane * inner];
        float v1 = x[base + (int64_t)(lane + 32) * inner];

        float sum = __fmaf_rn(v0, v0, v1 * v1);

        // Warp reduction
        sum += __shfl_down_sync(0xffffffff, sum, 16);
        sum += __shfl_down_sync(0xffffffff, sum, 8);
        sum += __shfl_down_sync(0xffffffff, sum, 4);
        sum += __shfl_down_sync(0xffffffff, sum, 2);
        sum += __shfl_down_sync(0xffffffff, sum, 1);

        float inv_rms = __shfl_sync(0xffffffff, rsqrtf(sum / 64.0f + eps), 0);

        out[base + (int64_t)lane * inner]        = v0 * inv_rms;
        out[base + (int64_t)(lane + 32) * inner] = v1 * inv_rms;

        inst += (int64_t)gridDim.x * 4;
    }
}

torch::Tensor rmsnorm_cuda(torch::Tensor x, double eps) {
    if (x.is_cuda() && x.dtype() == torch::kFloat32 && x.is_contiguous() && x.dim() >= 2 && x.size(1) == 64) {
        int64_t batch = x.size(0);
        int64_t C     = 64;
        int64_t inner = x.numel() / (batch * C);
        int64_t total_instances = batch * inner;

        auto out = torch::empty_like(x);

        // 4 warps per block, each warp handles one instance
        // grid covers all instances
        int threads = 128;  // 4 warps
        int warps_per_block = 4;
        int64_t blocks = (total_instances + warps_per_block - 1) / warps_per_block;
        // Cap blocks to avoid excessive launch overhead
        if (blocks > 65535) blocks = 65535;

        rmsnorm_warp64_kernel<<<(unsigned int)blocks, threads>>>(
            x.data_ptr<float>(),
            out.data_ptr<float>(),
            inner,
            total_instances,
            (float)eps
        );
        return out;
    }
    // Fallback
    auto x2 = x * x;
    auto mean_sq = x2.mean(1, /*keepdim=*/true);
    return x / torch::sqrt(mean_sq + (double)eps);
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs RMS Normalization.
        """
    def __init__(self, num_features: int, eps: float = 1e-5):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the RMSNorm layer.

                Args:
                    num_features (int): Number of features in the input tensor.
                    eps (float, optional): A small value added to the denominator to avoid division by zero. Defaults to 1e-5.
                """
        self.num_features = num_features
        self.eps = eps
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if x.is_cuda:
                    return _stark_get_extension().rmsnorm_cuda(x, float(self.eps))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        rms = torch.sqrt(torch.mean(x * x, dim=1, keepdim=True) + self.eps)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        return x / rms
