CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor rmsnorm_cuda(torch::Tensor x, double eps);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rmsnorm_cuda", &rmsnorm_cuda, "Fused RMSNorm CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Out-of-place RMSNorm kernel with grid-stride loop.
// Each block handles multiple spatial instances via grid-stride.
// blockDim.x = 64 (one thread per channel for C=64).
__global__ void rmsnorm_kernel_outofplace(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t total_instances,
    int C,
    int inner,
    float eps
) {
    __shared__ float smem[64];

    for (int64_t inst = (int64_t)blockIdx.x; inst < total_instances; inst += (int64_t)gridDim.x) {
        int n   = (int)(inst / inner);
        int hw  = (int)(inst % inner);
        int c   = threadIdx.x;

        int64_t base = (int64_t)n * C * inner + hw;
        float val = x[base + (int64_t)c * inner];

        smem[c] = val * val;
        __syncthreads();

        // Tree reduction over 64 elements
        for (int stride = 32; stride > 0; stride >>= 1) {
            if (c < stride) {
                smem[c] += smem[c + stride];
            }
            __syncthreads();
        }

        float inv_rms = rsqrtf(smem[0] / (float)C + eps);
        __syncthreads();

        out[base + (int64_t)c * inner] = val * inv_rms;
    }
}

// Vectorized version using float4 for C=64 (each thread handles 4 channels)
// blockDim.x = 16 threads, each thread covers 4 channels via float4
__global__ void rmsnorm_kernel_vec4(
    const float* __restrict__ x,
    float* __restrict__ out,
    int64_t total_instances,
    int inner,
    float eps
) {
    const int C = 64;
    __shared__ float smem[16];

    for (int64_t inst = (int64_t)blockIdx.x; inst < total_instances; inst += (int64_t)gridDim.x) {
        int n  = (int)(inst / inner);
        int hw = (int)(inst % inner);
        int t  = threadIdx.x; // 0..15

        // Each thread loads 4 consecutive channels (stride=inner between channels)
        // Channel indices: t*4, t*4+1, t*4+2, t*4+3
        int64_t base = (int64_t)n * C * inner + hw;
        float v0 = x[base + (int64_t)(t*4+0) * inner];
        float v1 = x[base + (int64_t)(t*4+1) * inner];
        float v2 = x[base + (int64_t)(t*4+2) * inner];
        float v3 = x[base + (int64_t)(t*4+3) * inner];

        float partial = __fmaf_rn(v0,v0, __fmaf_rn(v1,v1, __fmaf_rn(v2,v2, v3*v3)));
        smem[t] = partial;
        __syncthreads();

        // Reduce 16 elements
        if (t < 8) smem[t] += smem[t+8];
        __syncthreads();
        if (t < 4) smem[t] += smem[t+4];
        __syncthreads();
        if (t < 2) smem[t] += smem[t+2];
        __syncthreads();
        if (t < 1) smem[t] += smem[t+1];
        __syncthreads();

        float inv_rms = rsqrtf(smem[0] / (float)C + eps);
        __syncthreads();

        out[base + (int64_t)(t*4+0) * inner] = v0 * inv_rms;
        out[base + (int64_t)(t*4+1) * inner] = v1 * inv_rms;
        out[base + (int64_t)(t*4+2) * inner] = v2 * inv_rms;
        out[base + (int64_t)(t*4+3) * inner] = v3 * inv_rms;
    }
}

torch::Tensor rmsnorm_cuda(torch::Tensor x, double eps) {
    if (x.is_cuda() && x.dtype() == torch::kFloat32 && x.is_contiguous() && x.dim() >= 2) {
        int C = (int)x.size(1);
        if (C == 64) {
            int64_t batch = x.size(0);
            int64_t inner = x.numel() / (batch * C);
            int64_t total_instances = batch * inner;

            auto out = torch::empty_like(x);
            const float* x_ptr = x.data_ptr<float>();
            float* out_ptr = out.data_ptr<float>();

            // Limit grid size to avoid launching 29M blocks
            int max_blocks = 65536;
            int grid = (int)std::min((int64_t)max_blocks, total_instances);

            // Use vectorized kernel (16 threads, 4 channels each)
            rmsnorm_kernel_vec4<<<grid, 16>>>(
                x_ptr, out_ptr, total_instances, (int)inner, (float)eps);
            return out;
        } else if (C > 0 && C <= 1024 && (C & (C - 1)) == 0) {
            int64_t batch = x.size(0);
            int64_t inner = x.numel() / (batch * C);
            int64_t total_instances = batch * inner;

            auto out = torch::empty_like(x);
            const float* x_ptr = x.data_ptr<float>();
